/**
 * The Stolen Blessing
 * -------------------
 * Rebekah dresses Jacob in Esau's clothes and goatskins; the blind Isaac feels the hands and blesses the wrong son. Stage: a tent at night, an old blind patriarch reaching out, a trembling younger son, the smell of the field in the garments; a lamp's last light, the blessing spoken.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dusk · hero: tent
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, tent, firepit, wheat, person } from './jacob-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1751333571, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -21.9, 0, -25.2, 1.32, 0xd8c8a0, W.r() * 6);
    tent(W, group, 6.1, 0, -1.2, 0.90, 0xd8c8a0, W.r() * 6);
    tent(W, group, -1.8, 0, -2.9, 0.94, 0x8a6a44, W.r() * 6);
    tent(W, group, -24.8, 0, -5.3, 0.92, 0x8a6a44, W.r() * 6);
    firepit(W, group, 6.0, 0, -3.1, 1.0);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x321d0f, head: 0x382112 });

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x060402, 0.2);
    W.disc([0, 5, -10], 5, 0x3b2212, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2d1a0e, ry: -0.33, s: 1.00 });

    return W.finish();
}

export default { build };
